cards.css:
:root {
  --warna-utama: #e67e22;
  --sudut: 8px;
}

.kartu {
  border: 2px solid var(--warna-utama);
  border-radius: var(--sudut);
  padding: 20px;
}

h2 {
  color: var(--warna-utama);
}

button {
  background-color: var(--warna-utama);
  border-radius: var(--sudut);
  border: none;
  color: white;
  padding: 10px 15px;
}

